import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { StrategyRunStreamError } from "../../backtestRunStream.js";
import { readStrategyRunStatusStream, StrategyRunContractError, type StrategyRunStatus } from "../strategyRun.js";

// Generated by the backend tests from what `/strategy-runs/{id}/events` streams.
const COMPLETED = JSON.parse(readFileSync(new URL("../../../../../tests/fixtures/strategy-run-stream/host-completed.strategy-run-stream.json",
  import.meta.url), "utf8")) as { status: Record<string, unknown> } & Record<string, unknown>;
const RUN = "bt_fixture";

function running(state = "QUEUED", generation = 1) {
  return { ...COMPLETED, terminal: false, progress: { sequence: 3, created_at_ms: 1 },
    status: { ...COMPLETED.status, state, source_state: state, terminal: false, result_available: false, generation } };
}

function body(frames: unknown[], { close = true } = {}): ReadableStream<Uint8Array> {
  const encoder = new TextEncoder();
  return new ReadableStream({
    start(controller) {
      for (const frame of frames) controller.enqueue(encoder.encode(`${JSON.stringify(frame)}\n`));
      if (close) controller.close();
    },
  });
}

const heartbeat = { schema: "candlescope.strategy-run-stream/1", type: "heartbeat", terminal: false };

test("statuses arrive in order and the stream resolves with the terminal one", async () => {
  const seen: string[] = [];
  const terminal = await readStrategyRunStatusStream({
    body: body([running("QUEUED"), heartbeat, running("RUNNING"), COMPLETED]), runId: RUN,
    onStatus: (status, progress) => seen.push(`${status.state}:${progress?.sequence ?? "-"}`),
  });
  assert.deepEqual(seen, ["QUEUED:3", "RUNNING:3", "COMPLETED:-"]);
  assert.equal(terminal.state, "COMPLETED");
  assert.equal(terminal.result_available, true);
});

test("a failed run is a terminal status, not a stream error", async () => {
  const failed = { ...COMPLETED, status: { ...COMPLETED.status, state: "FAILED", source_state: "FAILED", result_available: false,
    error: { code: "PROVIDER_CRASH_UNRECOVERABLE", message: "crash" } } };
  const status: StrategyRunStatus = await readStrategyRunStatusStream({ body: body([failed]), runId: RUN });
  assert.deepEqual(status.error, { code: "PROVIDER_CRASH_UNRECOVERABLE", message: "crash" });
});

test("server errors, early EOF and mixed runs or generations are refused", async () => {
  const error = { schema: "candlescope.strategy-run-stream/1", type: "error", terminal: true, run_id: RUN,
    error: { code: "RUN_IDENTITY_CHANGED", message: "reconnect" } };
  await assert.rejects(readStrategyRunStatusStream({ body: body([running(), error]), runId: RUN }),
    (failure: unknown) => failure instanceof StrategyRunStreamError && failure.code === "RUN_IDENTITY_CHANGED");
  await assert.rejects(readStrategyRunStatusStream({ body: body([running()]), runId: RUN }),
    (failure: unknown) => failure instanceof StrategyRunStreamError && failure.code === "STRATEGY_STREAM_INCOMPLETE");
  await assert.rejects(readStrategyRunStatusStream({ body: body([COMPLETED]), runId: "bt_other" }), StrategyRunContractError);
  await assert.rejects(readStrategyRunStatusStream({ body: body([running("RUNNING", 1), running("RUNNING", 2)]), runId: RUN }),
    /generation/);
  await assert.rejects(readStrategyRunStatusStream({ body: body([{ ...COMPLETED, terminal: false }]), runId: RUN }), /terminal/);
});

test("aborting stops reading without waiting for the run", async () => {
  const controller = new AbortController();
  const pending = readStrategyRunStatusStream({ body: body([running()], { close: false }), runId: RUN, signal: controller.signal,
    onStatus: () => controller.abort(new Error("consumer left")) });
  await assert.rejects(pending, /consumer left/);
});
